// 'memory' = the machine-code bytes the pipeline placed in memory.
// Each instruction is [opcode, ...operands], like a decoded bit pattern.
const memory = [
  ['MOV', 'eax', 3],   // 0x401044: a = 3
  ['MOV', 'edx', 4],   // 0x401048: b = 4
  ['ADD', 'eax', 'edx'],// 0x40104c: eax = a + b
  ['STORE', 'result', 'eax'], // 0x401054: result = eax
  ['CALL', 'printf'],  // 0x401058: printf("Result: %d", result)
  ['EXIT']             // return 0 -> exit
];
const regs = { eax: 0, edx: 0 };
const mem = { result: 0 };
let pc = 0; // the program counter set by the loader
function run() {
  while (pc < memory.length) {
    const ins = memory[pc];      // FETCH
    const op = ins[0];           // DECODE
    if (op === 'MOV') regs[ins[1]] = ins[2];          // EXECUTE
    else if (op === 'ADD') regs[ins[1]] += regs[ins[2]];
    else if (op === 'STORE') mem[ins[1]] = regs[ins[2]];
    else if (op === 'CALL') console.log('Result: ' + mem.result);
    else if (op === 'EXIT') break;
    pc++;                        // ADVANCE PC
  }
  return regs.eax;
}
